namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int MaxRatePoints = 10;

    public static int RatePoints(int subtotalCents, LoyaltyTier tier)
    {
        var baseRate = tier switch
        {
            LoyaltyTier.Green => 5,
            LoyaltyTier.Gold => 7,
            LoyaltyTier.Platinum => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(tier)),
        };
        var bonus = subtotalCents >= 20_000 ? 3 : subtotalCents >= 5_000 ? 1 : 0;
        return Math.Min(baseRate + bonus, MaxRatePoints);
    }

    // Integer division floors the (non-negative) discount to a whole cent.
    public static int DiscountCents(int subtotalCents, LoyaltyTier tier) =>
        (int)((long)subtotalCents * RatePoints(subtotalCents, tier) / 100);
}
